function backendJobTable(){let list=backendJobs().filter(x=>(!filterState.area||x.loc.toLowerCase().includes(filterState.area.toLowerCase()))&&(!filterState.station||(x.station+' '+x.line).toLowerCase().includes(filterState.station.toLowerCase()))&&(!filterState.style||x.style===filterState.style)&&(!filterState.jobType||x.employment===filterState.jobType)&&(!filterState.basis||x.salaryBasis===filterState.basis)&&(!filterState.min||x.hi>=Number(filterState.min))&&(!filterState.max||x.lo<=Number(filterState.max))&&(!filterState.listed||x.days<=Number(filterState.listed))&&(!filterState.relocation||x.relocation===filterState.relocation));if(filterState.sort==='recent')list.sort((a,b)=>a.days-b.days);if(filterState.sort==='salary')list.sort((a,b)=>b.hi-a.hi);if(filterState.sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));return `<div class="v17-table-wrap"><table class="v17-table"><thead><tr><th>Role</th><th>Employer</th><th>Location & Transit</th><th>Work style / Job type</th><th>Salary</th><th>Listed</th><th>Relocation</th></tr></thead><tbody>${list.map(x=>`<tr><td><strong>${esc(x.title)}</strong><small class="v17-muted">${esc(x.id)}</small></td><td>${esc(x.co)}</td><td>${esc(x.loc)}<div class="v17-muted">🚉 ${esc(x.station)} · ${esc(x.line)}</div></td><td>${esc(x.style)} / ${esc(x.employment)}</td><td>RM ${x.lo.toLocaleString()} – ${x.hi.toLocaleString()}<div class="v17-muted">${esc(x.salaryBasis)}</div></td><td>${x.days} days ago</td><td>${esc(x.relocation)}</td></tr>`).join('')||'<tr><td colspan="7">No jobs match filters.</td></tr>'}</tbody></table></div>`}
function backendJobApply(){const box=document.getElementById('v17-backend-job-list');if(box)box.innerHTML=backendJobTable()}
function backendJobView(){return `<div class="v17-kicker">PLATFORM / JOB INTELLIGENCE</div><h1>Advanced Job Filters</h1><p class="v17-muted">Analyze jobs by work style, commute, role type, salary period and posting age; illustrative data only.</p>${filterFields('backend')}<div id="v17-backend-job-list">${backendJobTable()}</div><button class="v17-secondary" onclick="BeamishMaster.exportJobData()">↓ Export filtered sample data</button>`}
function exportJobData(){const eligible=backendJobs().filter(x=>(!filterState.area||x.loc.toLowerCase().includes(filterState.area.toLowerCase()))&&(!filterState.station||(x.station+' '+x.line).toLowerCase().includes(filterState.station.toLowerCase()))&&(!filterState.style||x.style===filterState.style)&&(!filterState.jobType||x.employment===filterState.jobType)&&(!filterState.basis||x.salaryBasis===filterState.basis)&&(!filterState.min||x.hi>=Number(filterState.min))&&(!filterState.max||x.lo<=Number(filterState.max))&&(!filterState.listed||x.days<=Number(filterState.listed))&&(!filterState.relocation||x.relocation===filterState.relocation));const rows=[['Role','Employer','Location','Transport','Work style','Type','Salary Period','Min RM','Max RM','Listing Age Days','Relocation'],...eligible.map(x=>[x.title,x.co,x.loc,x.station,x.style,x.employment,x.salaryBasis,x.lo,x.hi,x.days,x.relocation])];downloadCsv('beamish_jobs_DEMO.csv',rows)}
